    [43625] = {name = "[q0]Monster - Axe, 1H Northrend C01 Stone (Executioner)", additional_info = "One-Hand Axe\\n1 - 4 Damage\\nDurability 20 / 20\\nSell Price: 2"},
    [43626] = {name = "[q2]Happy Pet Snack", additional_info = "Binds when picked up\\n(20)\\nSell Price: 250"},
    [43627] = {name = "Thrall's Gold Coin", additional_info = "Binds when picked up\\nGrom, may you rest well, old friend.\\n(20)\\nSell Price: 125"},
    [43628] = {name = "Lady Jaina Proudmoore's Gold Coin", additional_info = "Binds when picked up\\nArthas, my love, please come back to me.\\n(20)\\nSell Price: 125"},
    [43629] = {name = "Uther Lightbringer's Gold Coin", additional_info = "Binds when picked up\\nYoung Arthas must learn patience to temper his power. I will pray that he one day learns how to lead with care rather than force.\\n(20)\\nSell Price: 125"},
    [43630] = {name = "Tirion Fordring's Gold Coin", additional_info = "Binds when picked up\\nIt is my wish that my dear Taelan will grow strong enough to defend the people he cares for.\\n(20)\\nSell Price: 125"},
    [43631] = {name = "Teron's Gold Coin", additional_info = "Binds when picked up\\nWishes are a fool's pastime. Take this coin as payment for your precious Eye.\\n(20)\\nSell Price: 125"},
    [43632] = {name = "Sylvanas Windrunner's Gold Coin", additional_info = "Binds when picked up\\nI hope my sisters and I can grow up and get married together. This coin appears to be very old.\\n(20)\\nSell Price: 125"},
    [43633] = {name = "Prince Kael'thas Sunstrider's Gold Coin", additional_info = "Binds when picked up\\nThat young apprentice Jaina is quite attractive for a human. I hope she recognizes my elegance and power.\\n(20)\\nSell Price: 125"},
    [43634] = {name = "Lady Katrana Prestor's Gold Coin", additional_info = "Binds when picked up\\nListen, little wishing fountain. You'll give me all your power if you know what's good for you.\\n(20)\\nSell Price: 125"},
    [43635] = {name = "Kel'Thuzad's Gold Coin", additional_info = "Binds when picked up\\nSometimes... I wish someone would come along and just give me a big, long hug.\\n(20)\\nSell Price: 125"},
    [43636] = {name = "Chromie's Gold Coin", additional_info = "Binds when picked up\\nJust once, I wish someone would greet me without making a stupid joke about gnomes or time travel.\\n(20)\\nSell Price: 125"},
    [43637] = {name = "Brann Bronzebeard's Gold Coin", additional_info = "Binds when picked up\\nBrann Bronzebeard was here.\\n(20)\\nSell Price: 125"},
    [43638] = {name = "Arugal's Gold Coin", additional_info = "Binds when picked up\\nI wish someday to retire to my own tidy little estate, with a bunch of pet dogs to keep me company.\\n(20)\\nSell Price: 125"},
    [43639] = {name = "Arthas' Gold Coin", additional_info = "Binds when picked up\\nAlready, I've a kingdom in my prospects, a land to rule. What to ask for?  Perhaps a frozen scone...\\n(20)\\nSell Price: 125"},
    [43640] = {name = "Archimonde's Gold Coin", additional_info = "Binds when picked up\\nI wish to know how you survived my wrath, little fountain.\\n(20)\\nSell Price: 125"},
    [43641] = {name = "Anduin Wrynn's Gold Coin", additional_info = "Binds when picked up\\nI wish I would grow up, it feels like I've been 10 for years.\\n(20)\\nSell Price: 125"},
    [43643] = {name = "[q0]Prince Magni Bronzebeard's Silver Coin", additional_info = "I hope that my father and brothers outlive me. I'll not make much of a king.\\n(20)\\nSell Price: 62"},
    [43644] = {name = "[q0]A Peasant's Silver Coin", additional_info = "I'm so forgetful! I wish I had a better memory. Wait, didn't I already throw a coin into here?\\n(20)\\nSell Price: 62"},
    [43645] = {name = "[q0]Bent Fishing Hook", additional_info = "Looks like someone tried to fish in this fountain. Who would do such a thing?\\n(20)\\nSell Price: 62"},
    [43646] = {name = "Fountain Goldfish", additional_info = "(20)\\nSell Price: 62"},
    [43647] = {name = "Shimmering Minnow", additional_info = "(20)\\nSell Price: 62"},
    [43648] = {name = "[q2]RESILIENCE TEST RING DO NOT LOCALIZE", additional_info = "Binds when picked up\\nFinger\\nSell Price: 16778"},
    [43649] = {name = "[q4]ITEMIZER TEST RING DO NOT LOCALIZE", additional_info = "Binds when picked up\\nFinger\\nSell Price: 16778"},
    [43650] = {name = "Rusty Prison Key", additional_info = "Binds when picked up\\nResembles a key used to open underwater treasure chests...\\nSell Price: 62"},
    [43651] = {name = "[q5]Crafty's Pole", additional_info = "Binds when picked up\\nJust holding this fishing pole makes you shiver with excitement.  This is possibly the most amazing thing you've ever seen.\\nTwo-Hand Sword\\n447 - 672 Damage\\nDurability 95 / 95\\nSell Price: 374538"},
    [43652] = {name = "Slippery Eel", additional_info = "(20)\\nSell Price: 62"},
    [43653] = {name = "[q0]Partially Eaten Fish", additional_info = "Small tooth marks can be seen on the carcass.\\n(20)\\nSell Price: 62"},
    [43654] = {name = "[q3]Tome of the Dawn", additional_info = "Binds when equipped\\nSell Price: 1400"},
    [43655] = {name = "[q3]Book of Survival", additional_info = "Binds when equipped\\nSell Price: 1400"},
    [43656] = {name = "[q3]Tome of Kings", additional_info = "Binds when equipped\\nSell Price: 1400"},
    [43657] = {name = "[q3]Royal Guide of Escape Routes", additional_info = "Binds when equipped\\nSell Price: 1400"},
    [43658] = {name = "[q0]Partially Rusted File", additional_info = "The file has a slight green tinge to it.\\nSell Price: 62"},
    [43659] = {name = "[q0]Bloodied Prison Shank", additional_info = "The business end of this shank looks like profits were high this year.\\nOne-Hand\\n93 - 174 Damage\\nDurability 55 / 55\\nSell Price: 33319"},
    [43660] = {name = "[q3]Fire Eater's Guide", additional_info = "Binds when equipped\\nSell Price: 1400"},
    [43661] = {name = "[q3]Book of Stars", additional_info = "Binds when equipped\\nSell Price: 1400"},
    [43662] = {name = "Axe of the Plunderer", additional_info = "Binds to account\\nYou would expect this axe to be exceptionally sharp. It's not. The vrykul must have been relying upon his immense strength to hew through his foes."},
    [43663] = {name = "[q3]Stormbound Tome", additional_info = "Binds when equipped\\nSell Price: 1400"},
    [43664] = {name = "[q3]Manual of Clouds", additional_info = "Binds when equipped\\nSell Price: 1400"},
    [43665] = {name = "Keristrasza's Broken Heart", additional_info = "Binds to account\\nA tragic end to a sad tale. If only Malygos's abuse of Keristrasza hadn't driven her insane."},
    [43666] = {name = "[q3]Hellfire Tome", additional_info = "Binds when equipped\\nSell Price: 1400"},
    [43667] = {name = "[q3]Book of Clever Tricks", additional_info = "Binds when equipped\\nSell Price: 1400"},
    [43668] = {name = "Ley Line Tuner", additional_info = "Binds to account\\nYou're not quite sure what to make of it. It definitely seethes with arcane magic, but how can something so small be so important?"},
    [43669] = {name = "Locket of the Deceased Queen", additional_info = "Binds to account\\nThe only reminder that King Ymiron had of his love, Queen Angerboda."},
    [43670] = {name = "Prophet's Enchanted Tiki", additional_info = "Binds to account\\nIt seems to have lost all of its mojo with the demise of its bearer."},
    [43671] = {name = "Glyph of Corpse Explosion", additional_info = "(20)\\nSell Price: 100"},
    [43672] = {name = "Glyph of Pestilence", additional_info = "(20)\\nSell Price: 100"},
    [43673] = {name = "Glyph of Raise Dead", additional_info = "(20)\\nSell Price: 100"},
    [43674] = {name = "Glyph of Dash", additional_info = "(20)\\nSell Price: 100"},
    [43675] = {name = "[q0]Fandral Staghelm's Silver Coin", additional_info = "The War of the Shifting Sands... I wish I could forget it ever happened.\\n(20)\\nSell Price: 62"},
    [43676] = {name = "[q0]Arcanist Doan's Silver Coin", additional_info = "Oh, why won't you notice me? Abbendis, I would follow you anywhere. I wish you would notice me...\\n(20)\\nSell Price: 62"},
    [43677] = {name = "[q0]High Tinker Mekkatorque's Silver Coin", additional_info = "How does this fountain even work? I wonder if I could make one.\\n(20)\\nSell Price: 62"},
    [43678] = {name = "[q0]Antonidas' Silver Coin", additional_info = "Grant me the strength to accept the things that I cannot change, the courage to change the things I can and the wisdom to know the difference.\\n(20)\\nSell Price: 62"},
    [43679] = {name = "[q0]Muradin Bronzebeard's Silver Coin", additional_info = "May the Holy Light protect us on our expedition to the frozen north.\\n(20)\\nSell Price: 62"},
    [43680] = {name = "[q0]King Varian Wrynn's Silver Coin", additional_info = "I wish the uprising back at home would settle itself soon. I wouldn't want anyone to be hurt.\\n(20)\\nSell Price: 62"},
    [43681] = {name = "[q0]King Terenas Menethil's Silver Coin", additional_info = "May my son Arthas always act in the best interest of his people.\\n(20)\\nSell Price: 62"},
    [43682] = {name = "[q0]King Anasterian Sunstrider's Silver Coin", additional_info = "I hope young Kael'thas realizes that one day he must lead our people.\\n(20)\\nSell Price: 62"},
    [43683] = {name = "[q0]Khadgar's Silver Coin", additional_info = "Turalyon and Alleria, wherever you are, may you be well.\\n(20)\\nSell Price: 62"},
    [43684] = {name = "[q0]Medivh's Silver Coin", additional_info = "<You sense the ringing of three tones in your head, the third barely audible under the others' din.>\\n(20)\\nSell Price: 62"},
    [43685] = {name = "[q0]Maiev Shadowsong's Silver Coin", additional_info = "Where's Illidan?\\n(20)\\nSell Price: 62"},
    [43686] = {name = "[q0]Alleria's Silver Coin", additional_info = "May my sisters realize their full potential, the name Windrunner known as result of their deeds.\\n(20)\\nSell Price: 62"},
    [43687] = {name = "[q0]Aegwynn's Silver Coin", additional_info = "I really wish you mages would get your heads out from inside your own... books.\\n(20)\\nSell Price: 62"},
    [43688] = {name = "Weeping Quarry Document", additional_info = "Binds to account"},
    [43689] = {name = "Weeping Quarry Ledger", additional_info = "Binds to account"},
    [43690] = {name = "Weeping Quarry Schedule", additional_info = "Binds to account"},
    [43691] = {name = "Weeping Quarry Map", additional_info = "Binds to account"},
    [43692] = {name = "[q0]Monster - Sword, 2H Deathknight B01 Red (Red Glow)", additional_info = "Two-Hand Sword\\n1 - 2 Damage\\nDurability 20 / 20\\nSell Price: 2"},
    [43693] = {name = "Mojo Remnant of Akali", additional_info = "Binds to account\\nHard to believe that this is all that is left of the once mighty rhino god."},
    [43694] = {name = "[q0]Drowned Rat", additional_info = "Looks like falling in the soup pot did not work out so well this time.\\n(20)\\nSell Price: 62"},
    [43695] = {name = "Half Full Bottle of Prison Moonshine", additional_info = "Also useful for removing paint.\\n(20)\\nSell Price: 12"},
    [43696] = {name = "Half Empty Bottle of Prison Moonshine", additional_info = "Also useful for removing paint.\\n(20)\\nSell Price: 12"},
    [43697] = {name = "Artifact from the Nathrezim Homeworld", additional_info = "Binds to account\\nWhat strange construction. It must be one of the most alien-looking objects you've ever seen."},
    [43698] = {name = "[q3]Giant Sewer Rat", additional_info = "Binds when picked up\\nTeaches you how to summon this companion.\\nSell Price: 1000"},
    [43699] = {name = "The Curse of Flesh Disc", additional_info = "Binds to account\\nThere's information on this thing? What? There's no writing!"},
    [43700] = {name = "[q3]Geoset test boots do not localize", additional_info = "Binds when equipped\\nFeet Leather\\nDurability 50 / 50\\nSell Price: 50616"},
    [43701] = {name = "[q0]A Footman's Copper Coin", additional_info = "Wish I had that cousin of mine's duty to do nothing more than lug wood around carelessly...\\n(20)\\nSell Price: 62"},
    [43702] = {name = "[q0]Alonsus Faol's Copper Coin", additional_info = "One day, I hope to spread the path of the Light to the common people and teach them the value of the Three Virtues.\\n(20)\\nSell Price: 62"},
    [43703] = {name = "[q0]Ansirem's Copper Coin", additional_info = "I wish for happiness and acceptance for my daughter. She feels so out of place here...\\n(20)\\nSell Price: 62"},
    [43704] = {name = "[q0]Attumen's Copper Coin", additional_info = "Can I have a more comfortable saddle?  My hindquarters ache.\\n(20)\\nSell Price: 62"},
    [43705] = {name = "[q0]Danath's Copper Coin", additional_info = "I hope a troll dies, right... NOW.\\n(20)\\nSell Price: 62"},
    [43706] = {name = "[q0]Dornaa's Shiny Copper Coin", additional_info = "I wish that that jerk Arthas would fall into a pile of magnataur doody!\\n(20)\\nSell Price: 62"},
    [43707] = {name = "[q0]Eitrigg's Copper Coin", additional_info = "May Tirion's quest here in Northrend end with success, or may he die honorably in battle.\\n(20)\\nSell Price: 62"},
    [43708] = {name = "[q0]Elling Trias' Copper Coin", additional_info = "Being a rogue is hard work.  Someday I hope to pursue my life's one true passion...\\n(20)\\nSell Price: 62"},
    [43709] = {name = "[q0]Falstad Wildhammer's Copper Coin", additional_info = "I hope I end up in another book eventually.\\n(20)\\nSell Price: 62"},
    [43710] = {name = "[q0]Genn's Copper Coin", additional_info = "Pah, the fountains in Gilneas could grant ten times as many wishes as Dalaran's!\\n(20)\\nSell Price: 62"},
    [43711] = {name = "[q0]Inigo's Copper Coin", additional_info = "I wish I had my father back...\\n(20)\\nSell Price: 62"},
    [43712] = {name = "[q0]Krasus' Copper Coin", additional_info = "My prayers go out to my brothers and sisters who still suffer in the heart of Grim Batol. I WILL free them.\\n(20)\\nSell Price: 62"},
    [43713] = {name = "[q0]Kryll's Copper Coin", additional_info = "Boom. Now boom? I wish for a boom. Boom go! This coin must be broken, I wonder if it'll explode.\\n(20)\\nSell Price: 62"},
    [43714] = {name = "[q0]Landro Longshot's Copper Coin", additional_info = "I wish I'd kept that coin...\\n(20)\\nSell Price: 62"},
    [43715] = {name = "[q0]Molok's Copper Coin", additional_info = "Just once -- that's all I ask for, just once -- let the lass ride with me...\\n(20)\\nSell Price: 62"},
    [43716] = {name = "[q0]Murky's Copper Coin", additional_info = "I wish the water in Northrend wasn't so cold, it makes me sleepy.\\n(20)\\nSell Price: 62"},
    [43717] = {name = "[q0]Princess Calia Menethil's Copper Coin", additional_info = "I hope that handsome nobleman Lord Prestor notices me! He's so dreamy!\\n(20)\\nSell Price: 62"},
    [43718] = {name = "[q0]Private Marcus Jonathan's Copper Coin", additional_info = "I wish to grow a glorious, bushy mustache someday.\\n(20)\\nSell Price: 62"},
    [43719] = {name = "[q0]Salandria's Shiny Copper Coin", additional_info = "Someday, I'm gonna be more powerful than all of these mages!\\n(20)\\nSell Price: 62"},
    [43720] = {name = "[q0]Squire Rowe's Copper Coin", additional_info = "I hope I can get transferred out of Stormwind eventually and see Cersei again. Nothing good ever happens in this city.\\n(20)\\nSell Price: 62"},
    [43721] = {name = "[q0]Stalvan's Copper Coin", additional_info = "You mages refuse to provide me that which hastens the inevitable fate of two people in love, when only one is too naive to see it. I wish you all ruin.\\n(20)\\nSell Price: 62"},
    [43722] = {name = "[q0]Vereesa's Copper Coin", additional_info = "Asto're da shan're. Turus Fulo Il'amare, A'Talah Adore. Isera'duna...\\n(20)\\nSell Price: 62"},
    [43723] = {name = "[q0]Vargoth's Copper Coin", additional_info = "I wish Captain Sanders would hurry up with my shipment of wine.\\n(20)\\nSell Price: 62"},
    [43724] = {name = "Celestial Ruby Ring", additional_info = "Binds to account\\nRing? It's more like a necklace and a heavy one at that!"},
    [43725] = {name = "Glyph of Ghost Wolf", additional_info = "(20)\\nSell Price: 100"},
    [43726] = {name = "The Idle Crown of Anub'arak", additional_info = "Binds to account\\nThe crypt lord still carried it though he lost his royal title long ago when he entered the service of the Lich King."},
